/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.Map;

/**
 * Who and where of an event, from its attributes: what makes an error useful to debug and lets the
 * issues count the users and tenants they affect. The ids are the raw ones of the attributes; the
 * issues only keep them pseudonymized ({@link Pseudonym}).
 *
 * @param user {@code enduser.id} or {@code security.actor.uid} (empty when anonymous)
 * @param tenant {@code app.tenant} or {@code security.actor.tenant}
 * @param session {@code session.id} or {@code security.session.id}
 * @param route {@code http.route}
 * @param method {@code http.request.method}
 * @param status {@code http.response.status_code}
 * @param userAgent {@code user_agent.original} or {@code client.user_agent}
 */
public record EventContext(String user, String tenant, String session, String route,
    String method, String status, String userAgent) {

  public static final EventContext EMPTY = new EventContext(null, null, null, null, null, null, null);

  public static EventContext of(final Map<String, Object> attrs) {
    if (null == attrs || attrs.isEmpty()) {
      return EMPTY;
    }
    return new EventContext(first(attrs, "enduser.id", "security.actor.uid"),
        first(attrs, "app.tenant", "security.actor.tenant"),
        first(attrs, "session.id", "security.session.id"), first(attrs, "http.route"),
        first(attrs, "http.request.method", "http.method"),
        first(attrs, "http.response.status_code", "http.status_code"),
        first(attrs, "user_agent.original", "client.user_agent"));
  }

  /** This context, with the empty fields taken from {@code other} (the root span of the trace). */
  public EventContext orElse(final EventContext other) {
    if (null == other) {
      return this;
    }
    return new EventContext(pick(user, other.user), pick(tenant, other.tenant),
        pick(session, other.session), pick(route, other.route), pick(method, other.method),
        pick(status, other.status), pick(userAgent, other.userAgent));
  }

  /** Who suffered it: the user, or else the browser session. */
  public String who() {
    return null != user ? "user:" + user : null != session ? "session:" + session : null;
  }

  private static String pick(final String value, final String fallback) {
    return null != value ? value : fallback;
  }

  private static String first(final Map<String, Object> attrs, final String... keys) {
    for (String key : keys) {
      Object value = attrs.get(key);
      if (null != value) {
        String text = String.valueOf(value).trim();
        // An anonymous actor has an empty uid
        if (!text.isEmpty() && !"null".equals(text)) {
          return text;
        }
      }
    }
    return null;
  }
}
